// Color conversion utilities from scale.js
function toLinear(channel) {
  return channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
}

function fromLinear(channel) {
  return channel <= 0.0031308 ? channel * 12.92 : 1.055 * channel ** (1 / 2.4) - 0.055;
}

function hexToRgb(hex) {
  const h = hex.slice(1).toLowerCase();
  const r = Number.parseInt(h.slice(0, 2), 16) / 255;
  const g = Number.parseInt(h.slice(2, 4), 16) / 255;
  const b = Number.parseInt(h.slice(4, 6), 16) / 255;
  return [r, g, b];
}

function hexToOklch(hex) {
  const [r, g, b] = hexToRgb(hex).map(toLinear);
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  const L = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const A = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const B = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  return {
    l: L,
    c: Math.hypot(A, B),
    h: Math.atan2(B, A) * 180 / Math.PI
  };
}

function normalizeHue(h) {
  while (h < 0) h += 360;
  while (h >= 360) h -= 360;
  return h;
}

function isBrandishColor(hex) {
  const oklch = hexToOklch(hex);
  const h = normalizeHue(oklch.h);
  // Hue 195-240 (navy/blue range), saturation > 0.12
  return h >= 195 && h <= 240 && oklch.c > 0.12;
}

function parseColorLiteral(literal) {
  if (literal.startsWith('#')) {
    const body = literal.slice(1).toLowerCase();
    if (body.length === 3 || body.length === 4) {
      const r = body.slice(0, 1);
      const g = body.slice(1, 2);
      const b = body.slice(2, 3);
      const hex = `#${r}${r}${g}${g}${b}${b}`;
      return { hex, alpha: 1 };
    }
    if (body.length === 6 || body.length === 8) {
      const alpha = body.length === 8 ? Number.parseInt(body.slice(6, 8), 16) / 255 : 1;
      return { hex: `#${body.slice(0, 6)}`, alpha };
    }
    return null;
  }

  try {
    const parts = literal
      .slice(literal.indexOf('(') + 1, -1)
      .split(/[,\s/]+/u)
      .filter(Boolean);
    if (parts.length < 3) return null;

    const channels = parts.slice(0, 3).map(p => Number(p.replace('%', '')));
    if (channels.some(n => !Number.isFinite(n))) return null;
    const hex = `#${channels.map(n => Math.round(n).toString(16).padStart(2, '0')).join('')}`;

    let alpha = 1;
    if (parts[3]) {
      alpha = parts[3].endsWith('%') ? Number(parts[3].slice(0, -1)) / 100 : Number(parts[3]);
    }
    return Number.isFinite(alpha) ? { hex, alpha } : null;
  } catch {
    return null;
  }
}

