console.log(`✓ TASK 3: Found ${missedTokens.size} tokens with missed brand colors`);
console.log(`  Unique missed hex values: ${missedHexes.size}`);

// TASK 4: Compute OKLab distances for each missed hex
function oklabDistance(hex1, hex2) {
  const c1 = hexToOklch(hex1);
  const c2 = hexToOklch(hex2);
  // Convert h back to radians for distance
  const h1 = c1.h * Math.PI / 180;
  const h2 = c2.h * Math.PI / 180;
  const a1 = c1.c * Math.cos(h1);
  const b1 = c1.c * Math.sin(h1);
  const a2 = c2.c * Math.cos(h2);
  const b2 = c2.c * Math.sin(h2);
